<template><el-card><div class="toolbar"><el-input v-model="q" placeholder="搜索学号" clearable/><el-select v-model="status" placeholder="全部状态" clearable><el-option label="待人工审核" value="review"/><el-option label="审核通过待交付" value="approved"/></el-select><el-button @click="selectAll">全选筛选结果</el-button><el-button type="success" @click="batch('approved')">批量通过</el-button><el-button type="danger" @click="batch('rejected')">批量退回</el-button></div><el-table :data="filtered" @selection-change="rows=$event" row-key="id"><el-table-column type="selection" width="50"/><el-table-column prop="id" label="学号"/><el-table-column prop="status" label="状态"/></el-table></el-card></template><script setup>import{ref,computed}from'vue';const props=defineProps({students:Array});const emit=defineEmits(['refresh','message']);const q=ref(''),status=ref(''),rows=ref([]);const filtered=computed(()=>props.students.filter(x=>(!q.value||x.id.includes(q.value))&&(!status.value||x.status===status.value)));const selectAll=()=>rows.value=filtered.value;const batch=async(decision)=>{if(!rows.value.length)return emit('message','请先选择学生');const r=await fetch('/api/v1/reviews/batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({student_ids:rows.value.filter(x=>x.status==='review').map(x=>x.id),decision,reason:''})});if(!r.ok)return emit('message',(await r.json()).message||'批量审核失败');emit('message','批量审核完成');emit('refresh')}</script>